B.bwO=new A.d6("Metrit, negatif enerji, k\u0131zg\u0131nl\u0131\u011f\u0131n ka\xe7\u0131r\u0131lmas\u0131, mineral eksikli\u011fi",B.bay)
B.bfR=s(["Resmi t\xfcberk\xfclin testleri aksat\u0131lmas\u0131n; pozitifler mevzuata g\xf6re ayr\u0131ls\u0131n.","Sat\u0131n al\u0131nan hayvana karantina ve test; kesimde lezyon bulgusu kayda ge\xe7sin."],t.s)
