B.bwM=new A.d6("G\xf6bek enfeksiyonu yay\u0131lmas\u0131, Mycoplasma, travma",B.bgH)
B.b7r=s(["Do\u011fum m\xfcdahale e\u011fitimi; zincir ile \xe7ekmede do\u011fru y\xf6n ve ritim."],t.s)
B.bwC=new A.d6("Kaba/yanl\u0131\u015f do\u011fum m\xfcdahalesi, iri buza\u011f\u0131",B.b7r)
B.bb1=s(["Hipokalsemi \xf6nlemleri; prolapsus g\xf6r\xfclen hayvan derhal veterinere."],t.s)
B.bwY=new A.d6("G\xfc\xe7 do\u011fum, hipokalsemi, a\u015f\u0131r\u0131 \u0131k\u0131nma",B.bb1)
B.b7k=s(["A\u015f\u0131lama sonras\u0131 30 dk g\xf6zlem; adrenalin el alt\u0131nda; seri numaras\u0131 kayda."],t.s)
B.bwF=new A.d6("A\u015f\u0131/ila\xe7 reaksiyonu",B.b7k)
B.b9V=s(["Kuruda a\u015f\u0131r\u0131 ya\u011flanma \xf6nlensin; y\u0131lda 2 i\xe7 parazit program\u0131; yem mikotoksin analizi."],t.s)
B.bww=new A.d6("Ya\u011fl\u0131 karaci\u011fer, kelebek (Fasciola), mikotoksin",B.b9V)
